#pragma once#include <macros/AutoCloser.h>namespace ns_RsuXml{  class KLinearXmlW  {    enum    {      eSpaceShift = 4,    };    int m_shift;    bool m_lastElEnded;    bool m_bTexted;    KAutoCloser<FILE*> m_fX;  public:    KLinearXmlW()      : m_shift( -eSpaceShift )      , m_lastElEnded( true )      , m_bTexted( false )    {    }    bool Open4Write( LPCSTR pszFileOut, LPCSTR pszDeclaration = NULL )    {      FILE *pFile = NULL;      errno_t res = fopen_s( &pFile, pszFileOut, "wt" );      if( res )        return false;      m_fX.Assign( pFile, fclose );      fputs( "<?xml", m_fX );      if( pszDeclaration )      {        fputc( ' ', m_fX );        fprintf( m_fX, pszDeclaration );      }      fputs( "?>", m_fX );      EndLine();      return true;    }  protected:    friend class KLinearElement;    void OpenElement( LPCSTR pszName )    {      if( !m_fX )        return;      if( !m_lastElEnded )      {        fputc( '>', m_fX );        EndLine();      }      m_shift += eSpaceShift;      LineSpaces();      fprintf( m_fX, "<%s", pszName );      m_lastElEnded = false;    }    void CloseElement( LPCSTR pszName )    {      if( !m_fX )        return;      if( !m_lastElEnded )      {        m_lastElEnded = true;        fputc( '>', m_fX );        EndLine();      }      if( !m_bTexted )        LineSpaces();      m_bTexted = false;      fprintf( m_fX, "</%s>", pszName );      EndLine();      m_shift -= eSpaceShift;    }    void AddAttr( LPCSTR pszName, LPCSTR pszVal )    {      if( !m_fX )        return;      fputc( ' ', m_fX );      fprintf( m_fX, "%s=\"%s\"", pszName, pszVal );    }    void SetText( LPCSTR pszText )    {      if( !pszText || !*pszText )        return;      ASSD( !m_lastElEnded );      if( !m_lastElEnded )      {        m_lastElEnded = true;        fputc( '>', m_fX );      }      fputs( pszText, m_fX );      m_bTexted = true;    }  private:    void LineSpaces()    {      if( !m_fX )        return;      for( int i=0; i<m_shift; ++i )      {        fputc( ' ', m_fX );      }    }    void EndLine()    {      if( !m_fX )        return;      fputs( "\n", m_fX );    }  };  class KLinearElement  {    KLinearXmlW &m_doc;    LPCSTR m_pszElName;  protected:    KLinearElement();  public:    KLinearElement( KLinearXmlW &doc, LPCSTR pszName )      : m_doc( doc )      , m_pszElName( pszName )    {      if( m_pszElName )        m_doc.OpenElement( m_pszElName );    }    ~KLinearElement()    {      if( !m_pszElName )        return;      m_doc.CloseElement( m_pszElName );    }    bool Open( LPCSTR pszName )    {      if( m_pszElName )        return false;      m_pszElName = pszName;      m_doc.OpenElement( m_pszElName );      return true;    }    void SetAttribute( LPCSTR pszName, LPCSTR value )    {      m_doc.AddAttr( pszName, value );    }    void SetAttribute( LPCSTR pszName, int value )    {      char szBuf[32];      FormatPrint( szBuf, "%d", value );      m_doc.AddAttr( pszName, szBuf );    }    void SetAttribute( LPCSTR pszName, unsigned int value )    {      char szBuf[32];      FormatPrint( szBuf, "%u", value );      m_doc.AddAttr( pszName, szBuf );    }    void SetAttribute( LPCSTR pszName, double value )    {      char szBuf[32];      FormatPrint( szBuf, "%.17g", value );      m_doc.AddAttr( pszName, szBuf );    }    void SetAttribute( LPCSTR pszName, float value )    {      char szBuf[32];      FormatPrint( szBuf, "%.8g", value );      m_doc.AddAttr( pszName, szBuf );    }    void SetText( LPCSTR pszText )    {      m_doc.SetText( pszText );    }  private:    template<size_t _S>    int FormatPrint( char (&szBuf)[_S], LPCSTR pszFormat, ... )    {      va_list va;      va_start( va, pszFormat );      const int result = vsnprintf_s( szBuf, _S, _S-1, pszFormat, va );      va_end( va );      return result;    }  };};